create or replace function public.create_vehicle_maintenance_record(p_vehicle_id uuid,p_category text,p_title text,p_description text default null,p_priority text default 'medium',p_due_date date default null,p_due_odometer_km numeric default null,p_due_engine_hours numeric default null,p_cost_amount numeric default null,p_provider_name text default null,p_invoice_reference text default null,p_notes text default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_company_id uuid; v_id uuid; begin select company_id into v_company_id from public.vehicles where id=p_vehicle_id; if v_company_id is null then raise exception 'VEHICLE_NOT_ACCESSIBLE'; end if; if not public.can_manage_company(v_company_id) then raise exception 'FORBIDDEN'; end if; if nullif(trim(p_title),'') is null then raise exception 'TITLE_REQUIRED'; end if; insert into public.vehicle_maintenance_records(company_id,vehicle_id,category,title,description,priority,due_date,due_odometer_km,due_engine_hours,cost_amount,provider_name,invoice_reference,notes,created_by) values(v_company_id,p_vehicle_id,p_category,trim(p_title),nullif(trim(p_description),''),p_priority,p_due_date,p_due_odometer_km,p_due_engine_hours,p_cost_amount,nullif(trim(p_provider_name),''),nullif(trim(p_invoice_reference),''),nullif(trim(p_notes),''),auth.uid()) returning id into v_id; return v_id; end $$;
create or replace function public.create_vehicle_compliance_document(p_vehicle_id uuid,p_document_type text,p_title text,p_expires_on date,p_document_number text default null,p_issuer text default null,p_valid_from date default null,p_amount numeric default null,p_notes text default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_company_id uuid; v_id uuid; begin select company_id into v_company_id from public.vehicles where id=p_vehicle_id; if v_company_id is null then raise exception 'VEHICLE_NOT_ACCESSIBLE'; end if; if not public.can_manage_company(v_company_id) then raise exception 'FORBIDDEN'; end if; if nullif(trim(p_title),'') is null then raise exception 'TITLE_REQUIRED'; end if; insert into public.vehicle_compliance_documents(company_id,vehicle_id,document_type,title,document_number,issuer,valid_from,expires_on,amount,notes,created_by) values(v_company_id,p_vehicle_id,p_document_type,trim(p_title),nullif(trim(p_document_number),''),nullif(trim(p_issuer),''),p_valid_from,p_expires_on,p_amount,nullif(trim(p_notes),''),auth.uid()) returning id into v_id; return v_id; end $$;
grant execute on function public.create_vehicle_maintenance_record(uuid,text,text,text,text,date,numeric,numeric,numeric,text,text,text) to authenticated;
grant execute on function public.create_vehicle_compliance_document(uuid,text,text,date,text,text,date,numeric,text) to authenticated;
